  1→<script lang="ts">
  2→	// AC: @web-dashboard ac-4, ac-5, ac-33
  3→	import type { TaskSummary } from '@kynetic-ai/shared';
  4→	import { base } from '$app/paths';
  5→	import { Badge } from '$lib/components/ui/badge';
  6→	import {
  7→		Table,
  8→		TableBody,
  9→		TableCell,
 10→		TableHead,
 11→		TableHeader,
 12→		TableRow
 13→	} from '$lib/components/ui/table';
 14→	import { createEventDispatcher } from 'svelte';
 15→
 16→	export let tasks: TaskSummary[];
 17→	export let updatedTaskIds: Set<string> = new Set();
 18→	export let onSelectTask: ((taskId: string) => void) | undefined = undefined;
 19→
 20→	const dispatch = createEventDispatcher<{
 21→		select: string;
 22→	}>();
 23→
 24→	function selectTask(task: TaskSummary) {
 25→		console.log('[TaskList] selectTask called for:', task._ulid, task.title);
 26→		// Try callback first (Svelte 5 pattern), then dispatch (Svelte 4 pattern)
 27→		if (onSelectTask) {
 28→			console.log('[TaskList] Calling onSelectTask callback');
 29→			onSelectTask(task._ulid);
 30→		}
 31→		dispatch('select', task._ulid);
 32→	}
 33→
 34→	function getStatusColor(status: string): string {
 35→		const colors: Record<string, string> = {
 36→			pending: 'bg-status-pending text-status-pending-fg',
 37→			in_progress: 'bg-status-in-progress text-status-in-progress-fg',
 38→			pending_review: 'bg-status-pending-review text-status-pending-review-fg',
 39→			needs_work: 'bg-status-needs-work text-status-needs-work-fg',
 40→			blocked: 'bg-status-blocked text-status-blocked-fg',
 41→			completed: 'bg-status-completed text-status-completed-fg',
 42→			cancelled: 'bg-status-cancelled text-status-cancelled-fg'
 43→		};
 44→		return colors[status] || 'bg-status-cancelled text-status-cancelled-fg';
 45→	}
 46→
 47→	function formatStatus(status: string): string {
 48→		const labels: Record<string, string> = {
 49→			pending: 'Pending',
 50→			in_progress: 'In Progress',
 51→			pending_review: 'Pending Review',
 52→			needs_work: 'Needs Work',
 53→			blocked: 'Blocked',
 54→			completed: 'Completed',
 55→			cancelled: 'Cancelled'
 56→		};
 57→		return labels[status] || status;
 58→	}
 59→
 60→	function getPriorityColor(priority: number): string {
 61→		if (priority === 1) return 'text-red-600 font-bold';
 62→		if (priority === 2) return 'text-orange-600 font-semibold';
 63→		if (priority === 3) return 'text-yellow-600';
 64→		return 'text-gray-600';
 65→	}
 66→</script>
