    96→		// AC: @ui-session-stream ac-2 — Periodic refresh (every 3s for live sessions)
    97→		refreshTimer = setInterval(() => {
    98→			if (isLive) {
    99→				refreshEvents();
   100→			}
   101→		}, 3000);
   102→	});
   103→
   104→	onDestroy(() => {
   105→		off('agents', handleAgentEvent);
   106→		unsubscribe(['agents']);
   107→		if (refreshTimer) clearInterval(refreshTimer);
   108→	});
   109→</script>
   110→
   111→<div class="flex flex-col h-full">
   112→	<!-- Header -->
   113→	<div class="flex items-center gap-3 px-4 py-3 border-b flex-shrink-0">
   114→		<a
   115→			href="{base}/sessions"
   116→			class="text-muted-foreground hover:text-foreground transition-colors"
   117→			title="Back to sessions"
   118→		>
   119→			<ArrowLeft class="size-4" />
   120→		</a>
   121→		<div>
   122→			<h1 class="text-lg font-semibold">
   123→				Session
   124→				{#if session}
   125→					<span class="font-mono text-sm text-muted-foreground ml-1">{session.id.slice(0, 8)}</span>
   126→				{/if}
   127→			</h1>
   128→			{#if session}
   129→				<p class="text-xs text-muted-foreground">
   130→					{session.agent_type}
   131→					{#if isLive}
   132→						<span class="ds-session-active-dot size-1.5 rounded-full bg-status-completed inline-block ml-1"></span>
   133→						<span class="text-status-completed">Live</span>
   134→					{/if}
   135→				</p>
   136→			{/if}
   137→		</div>
   138→	</div>
   139→
   140→	<!-- Error -->
   141→	{#if error}
   142→		<div class="mx-4 mt-4 bg-destructive/10 text-destructive p-4 rounded-lg" role="alert" data-testid="session-error">
   143→			{error}
   144→		</div>
   145→	{/if}
   146→
   147→	<!-- Loading skeleton -->
   148→	{#if loading}
   149→		<SessionStreamSkeleton />
   150→	{:else if session}
