.ds-narrative-section {
  padding: 5rem 1.5rem 5rem;
  max-width: 56rem;
  margin: 0 auto;
}

.ds-narrative-section.ds-narrative-has-visuals {
  max-width: 72rem;
}

.ds-narrative-header {
  margin-bottom: 4rem;
  text-align: center;
}

.ds-narrative-eyebrow {
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--design-accent);
  margin-bottom: 0.75rem;
}

.ds-narrative-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 500;
  color: var(--design-fg);
  letter-spacing: -0.02em;
}

/* Chapters container */
.ds-narrative-chapters {
  position: relative;
}

/* Timeline — center line on desktop when visuals present */
.ds-narrative-timeline {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--design-border);
  transform: translateX(-0.5px);
  pointer-events: none;
}

/* Chapter */
.ds-narrative-chapter {
  padding: 3rem 0;
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 700ms ease-out, transform 700ms ease-out;
}

.ds-narrative-chapter.ds-narrative-chapter-visible {
  opacity: 1;
  transform: translateY(0);
}

.ds-narrative-chapter + .ds-narrative-chapter {
  border-top: 1px solid var(--design-border);
}

.ds-narrative-chapter-number {
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--design-accent);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.ds-narrative-chapter-dot {
  width: 6px;
  height: 6px;
  border-radius: 9999px;
  background: var(--design-accent);
}

.ds-narrative-chapter-title {
  font-size: 1.5rem;
  font-weight: 500;
  color: var(--design-fg);
  margin-bottom: 0.75rem;
  letter-spacing: -0.02em;
}

.ds-narrative-chapter-body {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--design-muted-fg);
  max-width: 36rem;
}

.ds-narrative-chapter-body em {
  color: var(--design-fg);
  font-style: normal;
}

/* Two-column layout for chapters with visuals */
.ds-narrative-chapter-with-visual {
  max-width: none;
}

.ds-narrative-chapter-with-visual + .ds-narrative-chapter-with-visual {
  border-top: none;
}

.ds-narrative-layout-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.ds-narrative-layout-grid .ds-narrative-chapter-body {
  max-width: none;
}

/* Visual on right: text first, visual second (default for even chapters) */
.ds-narrative-visual-right .ds-narrative-text-area {
  order: 1;
}
.ds-narrative-visual-right .ds-narrative-visual-area {
  order: 2;
}

/* Visual on left: visual first, text second (default for odd chapters) */
.ds-narrative-visual-left .ds-narrative-visual-area {
  order: 1;
}
.ds-narrative-visual-left .ds-narrative-text-area {
  order: 2;
}

.ds-narrative-visual-area {
  border-radius: var(--design-radius-lg);
  background: var(--design-card);
  border: 1px solid var(--design-border);
  padding: 1.5rem;
  overflow: hidden;
}

/* Responsive: stack on mobile */
@media (max-width: 768px) {
  .ds-narrative-section.ds-narrative-has-visuals {
    max-width: 56rem;
  }

  .ds-narrative-layout-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  /* Always text first, visual below on mobile */
  .ds-narrative-visual-left .ds-narrative-visual-area,
  .ds-narrative-visual-right .ds-narrative-visual-area {
    order: 2;
  }
  .ds-narrative-visual-left .ds-narrative-text-area,
  .ds-narrative-visual-right .ds-narrative-text-area {
    order: 1;
  }

  .ds-narrative-timeline {
    left: 0;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-narrative-chapter {
    opacity: 1;
    transform: none;
    transition: none !important;
  }
}

