		expect(href).toContain('/specs?ref=');
		expect(href).toContain(encodeURIComponent('ui-reference-display'));
	});

	it('generates plan URL', () => {
		const href = refHref('plan', '@plan-id');
		expect(href).toContain('/plans?ref=');
		expect(href).toContain(encodeURIComponent('@plan-id'));
	});

	it('generates session URL with normalized ref', () => {
		const href = refHref('session', '@session-id');
		expect(href).toContain('/sessions/session-id');
	});

	it('encodes special characters in refs', () => {
		const href = refHref('task', '@task with spaces');
		expect(href).toContain(encodeURIComponent('@task with spaces'));
	});
});

